//! 关键帧时长与缓动: 对齐 WebGAL 的 `changeFigure` / `setTransform` 语义。
//!
//! 旧实现把"到下一关键帧的整段跨度"当作动画时长, 于是每个 `setTransform` 都变成横跨数秒的
//! 运镜。这里用最小的 fixture 钉住三条规则:
//! 1. `setTransform` 的关键帧时间 = 语句执行时间, `enter_ms` = `-duration`;
//! 2. 不带 `-next` 的 `setTransform` 仍然会推进时间线 (表演结束后才继续);
//! 3. 换立绘 (`changeFigure` 首次出现) 标记 `snap_transform`, 只淡入不插值。

use std::path::PathBuf;

use webgal_video_export::{
    config::ExportConfig,
    project::Project,
    script::{ChoicePolicy, compile},
};

fn plan() -> webgal_video_export::plan::Plan {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/minimal");
    let project = Project::open(path).expect("open minimal fixture");
    let config = ExportConfig::default();
    let policy = ChoicePolicy::new(&config.choices);
    compile(&project, &config, &policy).expect("compile")
}

#[test]
fn set_transform_key_starts_at_statement_time() {
    let plan = plan();
    let track = plan
        .figures
        .iter()
        .find(|track| track.id == "fig-left")
        .expect("fig-left track");
    assert_eq!(track.keys.len(), 2, "changeFigure + setTransform");

    let enter = &track.keys[0];
    assert_eq!(enter.t_us, 0);
    assert!(enter.snap_transform, "首次出现的立绘只淡入");
    assert_eq!(enter.enter_ms, 300);
    // `-left` 的基准是 -430 (2560 坐标); 默认输出 1920 时缩放 0.75 → -323。
    assert_eq!(
        enter.transform.position.and_then(|position| position.x),
        Some(-323)
    );

    let transform = &track.keys[1];
    assert_eq!(
        transform.t_us, 0,
        "setTransform 从语句处开始, 不是 time + duration"
    );
    assert!(!transform.snap_transform, "同一立绘的位移要插值");
    assert_eq!(transform.enter_ms, 1000, "动画时长 = -duration");
    assert_eq!(transform.ease, "easeInOut", "未写 -ease 时默认 easeInOut");
    // setTransform x=200 是相对基准的偏移: (-430 + 200) × 0.75 = -172.5 → -173。
    assert_eq!(
        transform.transform.position.and_then(|position| position.x),
        Some(-173)
    );
}

#[test]
fn set_transform_without_next_advances_timeline() {
    let plan = plan();
    let first = plan.texts.first().expect("text segments");
    // 场上有 setTransform -duration=1000 (没有 -next), 之后才开始第一句。
    assert_eq!(first.start_us, 1_000_000);
}

#[test]
fn background_switch_snaps_and_fades() {
    let plan = plan();
    let key = plan.background.first().expect("background key");
    assert!(key.snap_transform, "换背景时位置直接生效");
    assert_eq!(key.enter_ms, 1500, "changeBg 默认入场 1500ms");
}
